import{z as A,x as p,o as e,c as B,q as r,j as s,D as n,d as t,s as i,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"Shannon 通信","description":"","frontmatter":{"title":"Shannon 通信","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/shannon-1948-paper.md","filePath":"cs/shannon-1948-paper.md","lastUpdated":1791413859000}'),h={name:"cs/shannon-1948-paper.md"};function d(c,a,m,C,u,f){const o=p("Mermaid");return e(),B("div",null,[a[2]||(a[2]=r('<h1 id="shannon-通信" tabindex="-1">Shannon 通信 <a class="header-anchor" href="#shannon-通信" aria-label="Permalink to &quot;Shannon 通信&quot;">​</a></h1><div class="epigraph"><p>通信是从有限集合里复现一次挑选；比特度量选择，噪声下的可靠速率有上限。</p><footer>—— Shannon, A Mathematical Theory of Communication, Bell System Technical Journal 1948</footer></div><p><a href="/cs/von-neumann-edvac">上一课</a>附录对照了存储程序草案。附录对照，不插入主干。主干已在<a href="/cs/von-neumann-edvac">比特作为区分</a>、<a href="/cs/entropy-bits">信息量与熵</a>、<a href="/cs/error-correcting-intuition">纠错码直觉</a>里用过字母表、熵与噪声；这里对照 <strong>1948 原文的问题</strong>：如何把通信从电路噪声里抽成数学，使信源编码与信道编码分开。不重推熵公式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主干第一课钉的是二元区分；熵课才引入分布。Shannon 原文的缺口是整条链：信源、编码器、信道、复现，以及两条定理——压缩不能低于熵，噪声信道有容量。这不是 EDVAC 的结构图，也不是可计算性。1949 年保密论文是另一篇，对称加密课已经点名。</p><p><span class="marginnote">比特在 1948 里是信息量的单位，也是二元符号。主干第一课故意先只取符号，把熵留给后课，避免第一课变成概率。</span></p><p><span class="marginnote">直觉类比：通信被抽象成「传答案」——出题人（信源）从题库里挑了一道题，收件人要复现的只是「挑的是哪道」这一件事，与题目的意义、情感全无关。把「语义」剥掉之后，通信才第一次变成可以计算的数学对象。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>信源：随机过程，熵率。无噪声：编码长度下界为熵。信道：转移概率，容量 \\(C=\\max I(X;Y)\\)。有噪声：码率低于容量则可任意可靠。主干纠错课只取直觉（冗余对抗翻转），不把随机编码证明插进课序。</p><p><span class="marginnote">数字实例：英文文本的熵率约每字符 1 比特出头，而 ASCII 给每字符固定 8 比特——理论上存在编码把英文压到约八分之一再略多；想压得更低就必然丢信息，熵这道下界没有任何工程手段能绕过。</span></p>',10)),(e(),s(l,null,{default:n(()=>[i(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E4%BF%A1%E6%BA%90%22%5D%20--%3E%20ENC%5B%22%E7%BC%96%E7%A0%81%22%5D%0A%20%20ENC%20--%3E%20CH%5B%22%E4%BF%A1%E9%81%93%22%5D%0A%20%20CH%20--%3E%20DEC%5B%22%E5%A4%8D%E7%8E%B0%E6%8C%91%E9%80%89%22%5D%0A%20%20SRC%20--%3E%20TRUNK%5B%22%E4%B8%BB%E5%B9%B2%3A%20%E6%AF%94%E7%89%B9%20%2F%20%E7%86%B5%20%2F%20%E7%BA%A0%E9%94%99%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"区分「符号」与「信息量」之后，压缩与纠错可以分家：一个去掉信源冗余，一个按信道加受控冗余。主干网络课的校验和只防随机错，与 Shannon 码不是同一对象；安全课的哈希更不是。本附录只对照原文如何切开这两层。",-1)),(e(),s(l,null,{default:n(()=>[i(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20M%5B%22%E5%8E%9F%E5%A7%8B%E6%B6%88%E6%81%AF%2C%20%E8%87%AA%E5%B8%A6%E5%86%97%E4%BD%99%22%5D%20--%3E%20SC%5B%22%E4%BF%A1%E6%BA%90%E7%BC%96%E7%A0%81%3A%20%E5%8E%8B%E7%BC%A9%E5%8E%BB%E5%86%97%E4%BD%99%22%5D%0A%20%20SC%20-.%20%22%E9%95%BF%E5%BA%A6%E4%B8%8B%E7%95%8C%20%3D%20%E7%86%B5%20H%22%20.-%3E%20CS%5B%22%E5%8E%8B%E7%BC%A9%E5%90%8E%E5%BA%8F%E5%88%97%22%5D%0A%20%20CS%20--%3E%20CC%5B%22%E4%BF%A1%E9%81%93%E7%BC%96%E7%A0%81%3A%20%E5%8A%A0%E5%8F%97%E6%8E%A7%E5%86%97%E4%BD%99%22%5D%0A%20%20CC%20-.%20%22%E9%80%9F%E7%8E%87%E4%B8%8A%E7%95%8C%20%3D%20%E5%AE%B9%E9%87%8F%20C%22%20.-%3E%20TX%5B%22%E7%A0%81%E5%AD%97%22%5D%0A%20%20TX%20--%3E%20CH%5B%22%E5%B8%A6%E5%99%AA%E4%BF%A1%E9%81%93%22%5D%0A%20%20CH%20--%3E%20DEC%5B%22%E8%A7%A3%E7%A0%81%E5%A4%8D%E7%8E%B0%E6%8C%91%E9%80%89%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p><span class="marginnote">常见误区：初学者容易以为「信道有噪声就必然出错」。Shannon 定理说的是：只要码率 \\lt 容量 \\(C\\)，就存在编码让差错率任意小——噪声不能消除，但可以被编码「绕过」；反过来码率一旦 \\gt \\(C\\)，任何编码都救不回来，这是硬边界不是工程余量。</span></p><h3 id="为何对照而不插入主干" tabindex="-1">为何对照而不插入主干 <a class="header-anchor" href="#为何对照而不插入主干" aria-label="Permalink to &quot;为何对照而不插入主干&quot;">​</a></h3><p>若把 1948 全文插在反相器之前，组成课会被信息论拖住。主干只要：先有区分，再有熵，再有纠错直觉。附录对照定理的分工，以及 1949 保密论与 1948 通信论不是同一篇。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要发明 arXiv 号，也不要把微信里的「信息」口语写成熵。下一篇对照 Knuth 如何把算法与分析写成多卷本，那是数据与算法主干已经用过的分析风格。</p><p>连续信道的容量公式与本栏离散比特课不是同一页演算；主干只取离散字母表这一层。</p><p>对照结束应回到主干<a href="/cs/bit-as-distinction">比特作为区分</a>与<a href="/cs/entropy-bits">信息量与熵</a>。容量证明不插入纠错直觉课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>附录对照 Shannon 1948：通信 = 复现挑选；熵与容量分家。</li><li>主干比特、熵、纠错课已取用；本篇不插入第一课之前。</li><li>1949 保密论另见对称加密课。</li><li>出处：Shannon, <em>BSTJ</em> 27, 1948。</li></ul>',9))])}const _=A(h,[["render",d]]);export{D as __pageData,_ as default};
